def parse_numbers(line):
    numbers = []
    for part in line.split():
        numbers.append(int(part))
    return numbers

print(parse_numbers("4 15 8"))

def min_max(values):
    low = values[0]
    high = values[0]
    for value in values:
        if value < low:
            low = value
        if value > high:
            high = value
    return low, high

smallest, largest = min_max([7, 2, 9, 4])
print(smallest, largest)

